(function () {
    "use strict";

    const CONFIG = {
        selectors: {
            component: ".msstore-chatonpage",
            textInput: ".msstore-chatonpage__text-input",
            submitButton: ".msstore-chatonpage__submit-button",
            promptPill: ".msstore-chatonpage__prompt-pill"
        },
        retryDelay: 500,
        maxRetries: 10
    };

    // Global state to prevent button mashing
    let isCurrentlySending = false;

    /**
     * Helper function to get the AEM Component API with retry logic
     * @returns {Promise<Object>} The AEM Component API object
     */
    function waitForStoreAssistantChatAPI() {
        return new Promise((resolve, reject) => {
            let attempts = 0;
            
            function checkAPI() {
                if (window.storeAssistantReactJsLib?.chat) {
                    resolve(window.storeAssistantReactJsLib.chat);
                    return;
                }
                
                attempts++;
                if (attempts >= CONFIG.maxRetries) {
                    reject(new Error(`AEM Component API not available after ${CONFIG.maxRetries} attempts`));
                    return;
                }
                
                setTimeout(checkAPI, CONFIG.retryDelay);
            }
            
            checkAPI();
        });
    }

    /**
     * Test function to force open chat - can be called from console for debugging
     */
    window.forceOpenChat = async function() {
        try {
            const api = await waitForStoreAssistantChatAPI();
            const result = await api.openChat();
            return result;
        } catch (error) {
            console.error('Error forcing chat open:', error);
        }
    };

    /**
     * Send a prompt using the AEM Component API with proper error handling
     * @param {string} message - The message to send
     * @returns {Promise<boolean>} Success status
     */
    async function sendPromptViaAPI(message) {
        try {
            // Global sending state protection
            if (isCurrentlySending) {
                return false;
            }

            const api = await waitForStoreAssistantChatAPI();
            
            // Set global sending flag
            isCurrentlySending = true;
            
            try {
                // Step 1: Check current state
                const isCurrentlyMinimized = await api.isMinimized();
                
                // Step 2: Always ensure chat is open
                const openResult = await api.openChat();
                
                // Step 3: Double-check and maximize if still minimized
                const isStillMinimized = await api.isMinimized();
                
                if (isStillMinimized) {
                    const maxResult = await api.maximizeChat();
                    
                    // Final verification
                    const finalState = await api.isMinimized();
                }
                
                // Step 4: Send the prompt
                const sendResult = await api.sendPrompt(message);

                return sendResult;
            } finally {
                // Always reset the sending flag after a delay to ensure UI updates
                setTimeout(() => {
                    isCurrentlySending = false;
                }, 1000);
            }
        } catch (error) {
            console.error("Error using AEM Component API:", error);
            isCurrentlySending = false;
            return false;
        }
    }

    /**
     * Initialize chat components on the page
     */
    async function initChatOnPage() {
        const chatComponents = document.querySelectorAll(CONFIG.selectors.component);

        if (!chatComponents.length) {
            console.warn("Chat on page component not found on page");
            return;
        }

        chatComponents.forEach(component => {
            const actionType = component.getAttribute("data-action-type");

            if (actionType === "textInputOnly" || actionType === "hybridInputAndPills") {
                initTextInputChat(component);
            }

            if (actionType === "promptPillsOnly" || actionType === "hybridInputAndPills") {
                initPromptPillsChat(component);
            }
        });

        // Initialize the chat through the API if available
        try {
            const api = await waitForStoreAssistantChatAPI();
            if (api.initChatOnPage) {
                await api.initChatOnPage();
            }
        } catch (error) {
            console.error("Error initializing chat via API:", error);
        }
    }

    /**
     * Update submit button state based on input content
     * @param {HTMLInputElement} textInput - The text input element
     * @param {HTMLButtonElement} submitButton - The submit button element
     */
    function updateSubmitButtonState(textInput, submitButton) {
        const hasContent = textInput.value.trim().length > 0;
        
        if (hasContent) {
            submitButton.classList.add("active");
            submitButton.disabled = false;
        } else {
            submitButton.classList.remove("active");
            submitButton.disabled = true;
        }
    }

    /**
     * Initialize text input functionality for a chat component
     * @param {Element} component - The chat component element
     */
    function initTextInputChat(component) {
        const submitButton = component.querySelector(CONFIG.selectors.submitButton);
        const textInput = component.querySelector(CONFIG.selectors.textInput);

        if (submitButton && textInput) {
            // Initialize button state
            updateSubmitButtonState(textInput, submitButton);

            // Update button state on input
            textInput.addEventListener("input", function() {
                updateSubmitButtonState(textInput, submitButton);
            });

            // Update button state on paste
            textInput.addEventListener("paste", function() {
                setTimeout(() => {
                    updateSubmitButtonState(textInput, submitButton);
                }, 0);
            });

            submitButton.addEventListener("click", function(event) {
                event.preventDefault();
                if (!submitButton.disabled) {
                    handleTextSubmission(textInput, submitButton);
                }
            });

            textInput.addEventListener("keypress", function(event) {
                if (event.key === "Enter") {
                    event.preventDefault();
                    if (!submitButton.disabled) {
                        handleTextSubmission(textInput, submitButton);
                    }
                }
            });
        }
    }

    /**
     * Initialize prompt pill functionality for a chat component with button mashing protection
     * @param {Element} component - The chat component element
     */
    function initPromptPillsChat(component) {
        const promptPills = component.querySelectorAll(CONFIG.selectors.promptPill);

        promptPills.forEach(pill => {
            // Set initial styles from data attributes
            const restColor = pill.getAttribute("data-rest-color");
            const restTextColor = pill.getAttribute("data-rest-text-color");
            const restIconColor = pill.getAttribute("data-rest-icon-color");
            const restStrokeColor = pill.getAttribute("data-rest-stroke-color");
            const pressedColor = pill.getAttribute("data-pressed-color");
            const pressedTextColor = pill.getAttribute("data-pressed-text-color");
            const pressedIconColor = pill.getAttribute("data-pressed-icon-color");
            const pressedStrokeColor = pill.getAttribute("data-pressed-stroke-color");
            const hoverColor = pill.getAttribute("data-hover-color");
            const hoverTextColor = pill.getAttribute("data-hover-text-color");
            const hoverIconColor = pill.getAttribute("data-hover-icon-color");
            const hoverStrokeColor = pill.getAttribute("data-hover-stroke-color");
            const svgIconPath = pill.querySelector("svg path");

            // Add hover effect for background color if hoverColor is set
            if (hoverColor || hoverTextColor || hoverIconColor || hoverStrokeColor) {
                pill.addEventListener("mouseenter", function() {
                    pill.style.background = hoverColor || "";
                    pill.style.color = hoverTextColor || "";
                    if (svgIconPath) svgIconPath.style.fill = hoverIconColor || "";
                    pill.style.borderColor = hoverStrokeColor || "";
                });
                pill.addEventListener("mouseleave", function() {
                    // Restore to original background color or pressed color if active
                    pill.style.background = pill.classList.contains("active") && pressedColor
                        ? pressedColor
                        : (restColor || "");
                    pill.style.color = pill.classList.contains("active") && pressedTextColor
                        ? pressedTextColor
                        : (restTextColor || "");
                    if (svgIconPath) {
                        svgIconPath.style.fill = pill.classList.contains("active") && pressedIconColor
                            ? pressedIconColor
                            : (restIconColor || "");
                    }
                    pill.style.borderColor = pill.classList.contains("active") && pressedStrokeColor
                        ? pressedStrokeColor
                        : (restStrokeColor || "");
                });
            }

            // Set initial styles if provided
            pill.style.background = restColor || "";
            pill.style.color = restTextColor || "";
            if (svgIconPath) svgIconPath.style.fill = restIconColor || "";
            pill.style.borderColor = restStrokeColor || "";

            pill.addEventListener("click", function() {
                // Prevent rapid clicking/button mashing at the UI level
                if (isCurrentlySending) {
                    return;
                }

                const message = pill.getAttribute("data-pill-value");

                // Visual feedback
                promptPills.forEach(p => {
                    p.classList.remove("active");
                    pill.style.background = restColor || "";
                    pill.style.color = restTextColor || "";
                    if (svgIconPath) svgIconPath.style.fill = restIconColor || "";
                    pill.style.borderColor = restStrokeColor || "";
                });
                pill.classList.add("active");
                // Set pressed color only when active, otherwise revert to default
                pill.style.background = pill.classList.contains("active") && pressedColor
                    ? pressedColor
                    : (restColor || "");
                pill.style.color = pill.classList.contains("active") && pressedTextColor
                    ? pressedTextColor
                    : (restTextColor || "");
                if (svgIconPath) svgIconPath.style.fill = pill.classList.contains("active") && pressedIconColor
                    ? pressedIconColor
                    : (restIconColor || "");
                pill.style.borderColor = pill.classList.contains("active") && pressedStrokeColor
                    ? pressedStrokeColor
                    : (restStrokeColor || "");

                if (message) {
                    sendPromptViaAPI(message)
                        .then(success => {
                            setTimeout(() => {
                                pill.classList.remove("active");
                                // Restore background color after sending
                                pill.style.background = restColor || "";
                                pill.style.color = restTextColor || "";
                                if (svgIconPath) svgIconPath.style.fill = restIconColor || "";
                                pill.style.borderColor = restStrokeColor || "";
                            }, 2000);
                        })
                        .catch(error => {
                            console.error("Error sending prompt pill message:", error);
                            pill.classList.remove("active");
                        });
                }
            });
        });
    }

    /**
     * Handle text input submission with button mashing protection
     * @param {HTMLInputElement} textInput - The text input element
     * @param {HTMLButtonElement} submitButton - The submit button element
     */
    function handleTextSubmission(textInput, submitButton) {
        // Prevent rapid submission
        if (isCurrentlySending) {
            return;
        }

        const message = textInput.value.trim();

        if (message) {
            const originalMessage = message;
            textInput.value = "";

            // Update button state after clearing input
            updateSubmitButtonState(textInput, submitButton);

            sendPromptViaAPI(originalMessage)
                .then(success => {
                    console.log("Text message result:", success);
                })
                .catch(error => {
                    console.error("Error sending text message:", error);
                    // Restore the input if sending failed
                    textInput.value = originalMessage;
                    // Update button state after restoring input
                    updateSubmitButtonState(textInput, submitButton);
                });
        }
    }

    // Initialize when DOM is ready
    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", initChatOnPage);
    } else {
        initChatOnPage();
    }

    // Listen for store assistant related events
    window.addEventListener("msChatScriptsLoaded", function() {
        setTimeout(initChatOnPage, 500);
    });

    const storeAssistantEvents = ["StoreAssistantLoaded", "StoreAssistantReady", "StoreAssistantInitialized"];
    storeAssistantEvents.forEach(eventName => {
        window.addEventListener(eventName, function() {
            setTimeout(initChatOnPage, 500);
        });
    });

    // Observe DOM for relevant changes to reinitialize when needed
    const observer = new MutationObserver(function(mutations) {
        for (const mutation of mutations) {
            if (mutation.addedNodes && mutation.addedNodes.length > 0) {
                for (const node of mutation.addedNodes) {
                    if (node.nodeType === Node.ELEMENT_NODE &&
                        (node.id === "msChatContainer" ||
                         node.id === "storeassistantroot" ||
                         node.classList.contains("copilot-container") ||
                         node.classList.contains("sa-default-entry-container"))) {
                        setTimeout(initChatOnPage, 500);
                        return;
                    }
                }
            }
        }
    });

    document.addEventListener("DOMContentLoaded", function () {
          const input = document.querySelector(".js-ghost-input");
          const ghostData = document.querySelector(".js-ghost-rotation-data");
          if (!input || !ghostData) return;

          const data = [...ghostData.querySelectorAll("li")].map(li => li.textContent);
          if (!data) return;
          const ghostTexts = data.map(t => t.trim()).filter(Boolean);
          if (ghostTexts.length === 0) return;

          let index = 0;
          let intervalId = null;

          function setGhostPlaceholder() {
              input.setAttribute("placeholder", ghostTexts[index]);
              index = (index + 1) % ghostTexts.length;
          }

          function startGhostRotation() {
              setGhostPlaceholder();
              intervalId = setInterval(setGhostPlaceholder, 3000);
          }

          function stopGhostRotation() {
              if (intervalId) {
                  clearInterval(intervalId);
                  intervalId = null;
              }
              input.setAttribute("placeholder", "");
          }

          input.addEventListener("focus", stopGhostRotation);
          input.addEventListener("blur", startGhostRotation);

          startGhostRotation();

           
         });


    observer.observe(document.body, {
        childList: true,
        subtree: true
    });

})();